// Compute growth intelligence from 7-day orders
const ordersRes = $('G1 — Fetch 7-Day Orders').item.json;
const orders = (ordersRes.data || []);
const sentiment = $('G0 — Fetch Revenue Sentiment').first().json.value?.sentiment || 'STABLE';

// Revenue & volume metrics
let totalRevenue = 0;
let orderCount = orders.length;
const dishCounts = {};
const hourBuckets = Array(24).fill(0);
const dayBuckets = {};

for (const o of orders) {
  const attr = o.attributes || o;
  const amount = Number(attr.total_amount || 0);
  totalRevenue += amount;

  // Peak hours
  try {
    const h = new Date(attr.createdAt).getHours();
    hourBuckets[h]++;
  } catch(e) {}

  // Top dishes from order_items
  const items = attr.order_items?.data || attr.order_items || [];
  for (const item of items) {
    const its = item.attributes || item;
    const label = its.label || its.item_code || 'Unknown';
    const qty = Number(its.qty || its.quantity || 1);
    const revenue = Number(its.line_total_cents || its.unit_price_cents || 0) * qty;
    dishCounts[label] = dishCounts[label] || { qty: 0, revenue: 0 };
    dishCounts[label].qty += qty;
    dishCounts[label].revenue += revenue;
  }
}

// Sort top dishes by revenue
const topDishes = Object.entries(dishCounts)
  .sort((a, b) => b[1].revenue - a[1].revenue)
  .slice(0, 5)
  .map(([label, data]) => ({ label, ...data }));

const peakHour = hourBuckets.indexOf(Math.max(...hourBuckets));
const avgBasket = orderCount > 0 ? Math.round(totalRevenue / orderCount) : 0;

// Churned customers with Platform-Agnostic Identities
const churnedRes = $('G2 — Fetch Churned Customers (Dynamic Churn)').item.json;
const churnedCustomers = (churnedRes.data || []).slice(0, 20).map(c => {
  const attr = c.attributes || c;
  const idents = (attr.identities?.data || attr.identities || []).map(i => i.attributes || i);
  const bestIdent = idents.find(i => i.is_primary) || idents[0];
  return {
    id: c.id, phone: attr.phone, name: attr.name, totalSpent: attr.total_spent || 0,
    bestChannel: bestIdent?.platform || 'whatsapp', channelId: bestIdent?.platform_user_id || attr.phone
  };
});

return [{ json: {
  sentiment,
  metrics: {
    totalRevenue, orderCount, avgBasket, peakHour, topDishes, churnedCount: churnedCustomers.length, period: '7d'
  },
  churnedCustomers
}}];

