// Parse LLM growth analysis
const metrics = $('G3 — Compute Growth Metrics').item.json.metrics;
const churnedCustomers = $('G3 — Compute Growth Metrics').item.json.churnedCustomers;
const sentiment = $('G3 — Compute Growth Metrics').item.json.sentiment;

let insight = `Semaine: ${metrics.orderCount} commandes. Sentiment: ${sentiment}.`;
let recommendations = [ `Relancer ${metrics.churnedCount} clients inactifs.` ];
let winback = `Hamburger chez Ralphé ! Ça vous tente ?`;

try {
  const raw = ($json.response || '').toString();
  const m = raw.match(/\{[\s\S]*\}/);
  if (m) {
    const parsed = JSON.parse(m[0]);
    if (parsed.insight) insight = parsed.insight;
    if (Array.isArray(parsed.recommendations)) recommendations = parsed.recommendations;
    if (parsed.winback_message) winback = parsed.winback_message;
  }
} catch(e) {}

return [{ json: { insight, recommendations, winback, metrics, churnedCustomers, sentiment, generatedAt: new Date().toISOString() }}];

